/* Pure project/timeline operations shared with validation tests. */
(function(root){
  const clamp=(n,min,max)=>Math.min(max,Math.max(min,Number(n)||0));
  function split(clips,index,time){const c=clips[index];if(!c||time<=c.start+.05||time>=c.end-.05)throw Error('分割位置須在所選片段內，且離兩端至少 0.05 秒。');return [...clips.slice(0,index),{start:c.start,end:time},{start:time,end:c.end},...clips.slice(index+1)]}
  function mapSubtitles(clips,subs){let offset=0,out=[];for(const c of clips){for(const s of subs){const start=Math.max(c.start,s.start),end=Math.min(c.end,s.end);if(end>start)out.push({start:offset+start-c.start,end:offset+end-c.start,text:s.text})}offset+=c.end-c.start}return out.sort((a,b)=>a.start-b.start)}
  function outputTime(clips,index,sourceTime){return clips.slice(0,index).reduce((t,c)=>t+c.end-c.start,0)+sourceTime-(clips[index]?.start||0)}
  function gainAt(time,total,volume,fadeIn,fadeOut){return clamp(volume,0,2)*Math.min(1,fadeIn>0?Math.max(0,time)/fadeIn:1,fadeOut>0?Math.max(0,total-time)/fadeOut:1)}
  function normalize(data,duration){if(!data||data.version!==2||!Array.isArray(data.clips)||!Array.isArray(data.subs))throw Error('這不是支援的課映專案。');if(!Number.isFinite(duration)||duration<=0)throw Error('影片長度無效。');const range=c=>c&&Number.isFinite(c.start)&&Number.isFinite(c.end)&&c.start>=0&&c.end>c.start&&c.end<=duration+.1;if(data.clips.length>1000||data.subs.length>50000||!data.clips.every(range)||!data.subs.every(s=>range(s)&&typeof s.text==='string'&&s.text.length<=240))throw Error('專案包含無效的片段或字幕。');const marks=Array.isArray(data.marks)?data.marks:[];if(marks.length>20000)throw Error('標註數量超過支援範圍。');for(const m of marks){if(!range(m)||!['pen','marker','ellipse','rect','arrow','cursor'].includes(m.tool)||!/^#[0-9a-f]{6}$/i.test(m.color)||!Number.isFinite(m.width)||m.width<1||m.width>200||!Array.isArray(m.points)||m.points.length>100000||!m.points.every(p=>p&&Number.isFinite(p.x)&&p.x>=0&&p.x<=1&&Number.isFinite(p.y)&&p.y>=0&&p.y<=1))throw Error('專案標註資料無效。')}return {version:2,name:String(data.name||'教學影片').slice(0,150),duration,clips:data.clips.map(c=>({start:c.start,end:Math.min(c.end,duration)})),subs:data.subs.map(s=>({start:s.start,end:Math.min(s.end,duration),text:s.text})),marks,settings:data.settings&&typeof data.settings==='object'?data.settings:{}}}
  const api={clamp,split,mapSubtitles,outputTime,gainAt,normalize};root.ClassCastCore=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
